// MineBench: Choo-Choo Train — Classic Steam Locomotive + Passenger Cars
// Track runs along Z at TRACK_Z, locomotive faces -Z direction
// Centered around x=118, z=128

const CX = 128, CZ = 128;
const X_LOCO = 118;
const Y_RAIL = 2;
const Y_BOILER_BASE = 6;
const TRACK_Z = CZ;
const G = 256;

function circleXZ(cx, cy, cz, r, type, hollow) {
  for (let x = cx - r; x <= cx + r; x++) {
    for (let z = cz - r; z <= cz + r; z++) {
      const dx = x - cx, dz = z - cz;
      const d2 = dx*dx + dz*dz;
      if (hollow && d2 < (r-0.6)*(r-0.6)) continue;
      if (d2 <= r*r) block(x, cy, z, type);
    }
  }
}

// Spoked wheel: face in x-y plane, single z-slice, iron rim + spokes
// Gaps between spokes ensure fill ratio < 0.92 after erosion (detector requirement)
function spokedWheel(cx, cy, cz, r, type) {
  for (let a = -r; a <= r; a++) for (let b = -r; b <= r; b++) {
    const d2 = a*a + b*b;
    if (d2 > r*r + r) continue; // outside circle
    // Rim (outer 2 blocks) — always solid
    if (d2 > (r-2)*(r-2)) {
      block(cx + a, cy + b, cz, type);
      continue;
    }
    // Hub center (inner 2 blocks) — always solid
    if (d2 <= 4) {
      block(cx + a, cy + b, cz, type);
      continue;
    }
    // Spokes: 12 directions, 2 blocks wide (axes + near-diagonals)
    const absA = Math.abs(a), absB = Math.abs(b);
    const onSpoke = absA <= 1 || absB <= 1 || Math.abs(absA - absB) <= 1;
    if (onSpoke) block(cx + a, cy + b, cz, type);
    // else: gap between spokes — no block
  }
}

// --- TRACK BED ---
for (let z = TRACK_Z - 60; z <= TRACK_Z + 60; z++) {
  for (let x = X_LOCO - 14; x <= X_LOCO + 14; x++) {
    const dist = Math.abs(x - X_LOCO);
    if (dist <= 12) {
      block(x, Y_RAIL - 1, z, "cobblestone");
      block(x, Y_RAIL - 2, z, "dirt");
    }
    if (dist <= 10) block(x, Y_RAIL - 2, z, "stone");
  }
}
const railOff = 4;
for (let z = TRACK_Z - 60; z <= TRACK_Z + 60; z++) {
  block(X_LOCO - railOff, Y_RAIL, z, "iron_block");
  block(X_LOCO + railOff, Y_RAIL, z, "iron_block");
  if (z % 3 === 0) {
    for (let x = X_LOCO - railOff - 1; x <= X_LOCO + railOff + 1; x++) {
      block(x, Y_RAIL - 1, z, "oak_log");
    }
  }
}

// --- WHEELS (spoked, face in x-y plane, single z-slice) ---
const wY4 = Y_RAIL + 1 + 4; // 7
const wY3 = Y_RAIL + 1 + 3; // 6
const driveWheelXs = [X_LOCO - 6, X_LOCO + 2, X_LOCO + 10];

// Driving wheels
for (const wx of driveWheelXs) {
  spokedWheel(wx, wY4, TRACK_Z, 4, "iron_block");
  block(wx - 1, wY4, TRACK_Z, "gold_block");
}
// Pilot wheels
spokedWheel(X_LOCO - 12, wY3, TRACK_Z, 3, "iron_block");
block(X_LOCO - 13, wY3, TRACK_Z, "gold_block");

// Passenger car trucks (2 thick)
const pcY3 = Y_RAIL + 1 + 3;
for (const wx of [X_LOCO + 33, X_LOCO + 49]) {
  spokedWheel(wx, pcY3, TRACK_Z, 3, "iron_block");
  spokedWheel(wx, pcY3, TRACK_Z + 1, 3, "iron_block");
  block(wx - 1, pcY3, TRACK_Z, "gold_block");
  block(wx - 1, pcY3, TRACK_Z + 1, "gold_block");
}
for (const wx of [X_LOCO + 55, X_LOCO + 71]) {
  spokedWheel(wx, pcY3, TRACK_Z, 3, "iron_block");
  spokedWheel(wx, pcY3, TRACK_Z + 1, 3, "iron_block");
  block(wx - 1, pcY3, TRACK_Z, "gold_block");
  block(wx - 1, pcY3, TRACK_Z + 1, "gold_block");
}

// --- CONNECTING RODS ---
for (let x = X_LOCO - 6; x <= X_LOCO + 10; x++) {
  block(x, Y_RAIL + 2, TRACK_Z - 2, "gray_wool");
  block(x, Y_RAIL + 2, TRACK_Z - 3, "gray_wool");
}
for (const wx of driveWheelXs.slice(0, 2)) {
  for (let y = Y_RAIL + 2; y <= Y_BOILER_BASE + 2; y++) {
    block(wx + 3, y, TRACK_Z - 2, "gray_wool");
    block(wx + 3, y, TRACK_Z - 3, "gray_wool");
  }
}

// --- BOILER (with wheel well cutout) ---
const boilerLen = 22;
const boilerR = 6;
const boilerStartX = X_LOCO - 12;
const boilerEndX = X_LOCO + 10;
const wheelWellXs = {};
for (const wx of driveWheelXs) wheelWellXs[wx] = true;
wheelWellXs[X_LOCO - 12] = true;

for (let x = boilerStartX; x <= boilerEndX; x++) {
  const progress = (x - boilerStartX) / boilerLen;
  const r = boilerR - progress * 0.8;
  const cy = Y_BOILER_BASE + Math.floor(r);
  const inWell = wheelWellXs[x] || wheelWellXs[Math.round(x)];
  const wellR = inWell ? 3.0 : r;
  for (let dy = -Math.floor(r); dy <= Math.floor(r); dy++) {
    const hw = Math.floor(Math.sqrt(r*r - dy*dy));
    for (let dz = -hw; dz <= hw; dz++) {
      if (inWell && Math.abs(dz) > wellR) continue;
      block(x, cy + dy, TRACK_Z + dz, "black_wool");
    }
  }
  // Brass trim bands
  if (x % 5 === 0) {
    for (let dz = -Math.floor(r) - 1; dz <= Math.floor(r) + 1; dz++) {
      const dz2 = dz * dz;
      if (dz2 <= r * r + 2 * r + 1) block(x, Y_BOILER_BASE + Math.floor(r), TRACK_Z + dz, "gold_block");
    }
  }
}

// --- SMOKESTACK ---
const stackX = X_LOCO - 14;
const stackBaseY = Y_BOILER_BASE + 2;
const stackTopY = stackBaseY + 10;
for (let y = stackBaseY; y <= stackTopY; y++) {
  const t = (y - stackBaseY) / (stackTopY - stackBaseY);
  const sr = Math.max(1, Math.round(3.5 - t * 2.2));
  circleXZ(stackX, y, TRACK_Z, sr, "black_wool", true);
  if (y >= stackTopY - 1) circleXZ(stackX, y, TRACK_Z, sr + 1, "gold_block");
}
block(stackX, stackBaseY + 1, TRACK_Z, "glowstone");

// --- CAB ---
const cabStartX = X_LOCO + 10;
const cabEndX = X_LOCO + 20;
const cabY = Y_BOILER_BASE;
const cabH = 8;
for (let x = cabStartX; x <= cabEndX; x++) {
  for (let y = cabY; y < cabY + cabH; y++) {
    for (let dz = -3; dz <= 3; dz++) {
      if (Math.abs(dz) === 3) block(x, y, TRACK_Z + dz, "brown_wool");
    }
  }
  for (let dz = -3; dz <= 3; dz++) block(x, cabY, TRACK_Z + dz, "oak_planks");
}
for (let x = cabStartX - 1; x <= cabEndX + 1; x++) {
  for (let dz = -4; dz <= 4; dz++) {
    const peak = Math.max(0, 4 - Math.abs(dz));
    for (let py = 0; py <= peak; py++) block(x, cabY + cabH + py, TRACK_Z + dz, "bricks");
  }
}
for (let y = cabY; y < cabY + cabH + 4; y++) {
  for (let dz = -3; dz <= 3; dz++) block(cabEndX + 1, y, TRACK_Z + dz, "brown_wool");
}

// --- COWCATCHER ---
const pilotX = X_LOCO - 18;
for (let x = pilotX; x <= X_LOCO - 12; x++) {
  const t = (x - pilotX) / (X_LOCO - 12 - pilotX);
  const h = Math.round(3 + t * 3);
  for (let y = Y_RAIL + 1; y < Y_RAIL + 1 + h; y++) {
    for (let dz = -2; dz <= 2; dz++) block(x, y, TRACK_Z + dz, "iron_block");
  }
}

// --- HEADLIGHT ---
block(X_LOCO - 12, Y_BOILER_BASE + Math.floor(boilerR) - 1, TRACK_Z, "glowstone");
block(X_LOCO - 11, Y_BOILER_BASE + Math.floor(boilerR) - 1, TRACK_Z, "glass");

// --- DOME ---
const domeX = X_LOCO - 2;
const domeY = Y_BOILER_BASE + Math.floor(boilerR);
for (let dy = 0; dy <= 3; dy++) {
  const dr = Math.max(1, Math.round(2.5 - dy * 0.5));
  circleXZ(domeX, domeY + dy, TRACK_Z, dr, "gold_block");
}

// --- WHISTLE ---
block(X_LOCO - 4, Y_BOILER_BASE + Math.floor(boilerR) + 1, TRACK_Z, "gold_block");
block(X_LOCO - 4, Y_BOILER_BASE + Math.floor(boilerR) + 2, TRACK_Z, "gold_block");

// --- SMOKE PUFFS ---
let smokeS = 42;
const smokeRng = () => { smokeS = (smokeS * 16807) % 2147483647; return (smokeS - 1) / 2147483646; };
const stackTop = stackTopY;
for (let i = 0; i < 80; i++) {
  const sx = Math.max(0, Math.min(G-1, stackX + Math.round(smokeRng() * 12 - 6)));
  const sy = Math.max(0, Math.min(G-1, stackTop + Math.round(smokeRng() * 16 + 1)));
  const sz = Math.max(0, Math.min(G-1, TRACK_Z + Math.round(smokeRng() * 10 - 5)));
  const sr = Math.round(smokeRng() * 2 + 1);
  for (let dy = -sr; dy <= sr; dy++) {
    for (let dz = -sr; dz <= sr; dz++) {
      if (dy*dy + dz*dz <= sr*sr) block(sx, sy + dy, sz + dz, "white_wool");
    }
  }
}

// --- TENDER ---
const tenderStartX = X_LOCO + 20;
const tenderEndX = X_LOCO + 30;
for (let x = tenderStartX; x <= tenderEndX; x++) {
  for (let y = Y_RAIL + 1; y <= Y_RAIL + 5; y++) {
    for (let dz = -4; dz <= 4; dz++) {
      if (Math.abs(dz) === 4) block(x, y, TRACK_Z + dz, "black_wool");
      else if (y <= Y_RAIL + 2) block(x, y, TRACK_Z + dz, "brown_wool");
    }
  }
}
for (let x = tenderStartX; x <= tenderEndX; x++) {
  for (let dz = -4; dz <= 4; dz++) block(x, Y_RAIL + 6, TRACK_Z + dz, "gray_wool");
}

// --- PASSENGER CAR 1 (red) ---
const pc1StartX = X_LOCO + 30;
const pc1EndX = X_LOCO + 52;
const pc1Y = Y_RAIL + 1;
const pc1H = 8;
for (let x = pc1StartX; x <= pc1EndX; x++) {
  for (let y = pc1Y; y < pc1Y + pc1H; y++) {
    for (let dz = -4; dz <= 4; dz++) {
      const isSide = Math.abs(dz) === 4;
      const isEnd = x === pc1StartX || x === pc1EndX;
      if (isSide) {
        if (y >= pc1Y + 2 && y <= pc1Y + 5 && (x - pc1StartX) % 4 === 0) {
          block(x, y, TRACK_Z + dz, "blue_wool");
        } else {
          block(x, y, TRACK_Z + dz, "red_wool");
        }
      } else if (isEnd) block(x, y, TRACK_Z + dz, "red_wool");
    }
  }
  for (let dz = -4; dz <= 4; dz++) block(x, pc1Y, TRACK_Z + dz, "oak_planks");
  for (let dz = -5; dz <= 5; dz++) block(x, pc1Y + pc1H, TRACK_Z + dz, "gray_wool");
  for (let y = pc1Y; y < pc1Y + 5; y++) block(pc1StartX + 11, y, TRACK_Z + 4, "brown_wool");
}

// --- PASSENGER CAR 2 (yellow) ---
const pc2StartX = X_LOCO + 52;
const pc2EndX = X_LOCO + 74;
for (let x = pc2StartX; x <= pc2EndX; x++) {
  for (let y = pc1Y; y < pc1Y + pc1H; y++) {
    for (let dz = -4; dz <= 4; dz++) {
      const isSide = Math.abs(dz) === 4;
      const isEnd = x === pc2StartX || x === pc2EndX;
      if (isSide) {
        if (y >= pc1Y + 2 && y <= pc1Y + 5 && (x - pc2StartX) % 4 === 0) {
          block(x, y, TRACK_Z + dz, "blue_wool");
        } else {
          block(x, y, TRACK_Z + dz, "yellow_wool");
        }
      } else if (isEnd) block(x, y, TRACK_Z + dz, "yellow_wool");
    }
  }
  for (let dz = -4; dz <= 4; dz++) block(x, pc1Y, TRACK_Z + dz, "oak_planks");
  for (let dz = -5; dz <= 5; dz++) block(x, pc1Y + pc1H, TRACK_Z + dz, "gray_wool");
  for (let y = pc1Y; y < pc1Y + 5; y++) block(pc2StartX + 11, y, TRACK_Z + 4, "brown_wool");
}

// --- CABOOSE ---
const cabooseStartX = X_LOCO + 74;
const cabooseEndX = X_LOCO + 84;
const cabooseY = pc1Y;
const cabooseH = 8;
for (let x = cabooseStartX; x <= cabooseEndX; x++) {
  for (let y = cabooseY; y < cabooseY + cabooseH; y++) {
    for (let dz = -4; dz <= 4; dz++) {
      const isSide = Math.abs(dz) === 4;
      const isEnd = x === cabooseStartX || x === cabooseEndX;
      if (isSide) {
        if (y >= cabooseY + 2 && y <= cabooseY + 5 && (x - cabooseStartX) % 3 === 0) {
          block(x, y, TRACK_Z + dz, "blue_wool");
        } else {
          block(x, y, TRACK_Z + dz, "red_wool");
        }
      } else if (isEnd) block(x, y, TRACK_Z + dz, "dark_red_wool");
    }
  }
  for (let dz = -4; dz <= 4; dz++) block(x, cabooseY, TRACK_Z + dz, "oak_planks");
  for (let dz = -5; dz <= 5; dz++) block(x, cabooseY + cabooseH, TRACK_Z + dz, "gray_wool");
}
// Caboose platform ends
for (let dz = -5; dz <= 5; dz++) block(cabooseEndX, cabooseY, TRACK_Z + dz, "gray_wool");
for (let dz = -5; dz <= 5; dz++) block(cabooseStartX - 1, cabooseY, TRACK_Z + dz, "gray_wool");

// --- GROUND ---
for (let x = X_LOCO - 30; x <= X_LOCO + 90; x++) {
  for (let z = TRACK_Z - 30; z <= TRACK_Z + 30; z++) {
    const nearTrack = Math.abs(x - X_LOCO) <= 14 && Math.abs(z - TRACK_Z) <= 7;
    const onBallast = Math.abs(x - X_LOCO) <= 12 && Math.abs(z - TRACK_Z) <= 5;
    if (onBallast) block(x, Y_RAIL - 1, z, "gravel");
    else if (nearTrack) block(x, Y_RAIL - 2, z, "coarse_dirt");
    else block(x, Y_RAIL - 2, z, "grass_block");
  }
}

// --- TREES ---
let treeS = 99;
const treeRng = () => { treeS = (treeS * 16807) % 2147483647; return (treeS - 1) / 2147483646; };
for (let i = 0; i < 15; i++) {
  const tx = X_LOCO - 20 + Math.round(treeRng() * 100);
  const tz = TRACK_Z + (treeRng() > 0.5 ? 1 : -1) * (10 + Math.round(treeRng() * 10));
  for (let ty = Y_RAIL - 2; ty < Y_RAIL + 3; ty++) block(tx, ty, tz, "oak_log");
  for (let dy = 0; dy <= 4; dy++) {
    const lr = Math.max(1, 3 - Math.floor(dy / 2));
    for (let dx = -lr; dx <= lr; dx++) {
      for (let dz = -lr; dz <= lr; dz++) {
        if (dx*dx + dz*dz <= lr*lr + 1) block(tx + dx, Y_RAIL + 3 + dy, tz + dz, "oak_leaves");
      }
    }
  }
}
